return ['domain'=>NULL,'plural-forms'=>'nplurals=3; plural=(n == 1) ? 0 : ((n >= 2 && n <= 4) ? 1 : 2);','language'=>'cs_CZ','project-id-version'=>'babilim-0.1.0-cs_CZ-babilim-0.1.0-cs_CZ-20261030T020946','pot-creation-date'=>'2026-10-30T06:25:13+00:00','po-revision-date'=>'2026-10-30T06:25:13+00:00','x-generator'=>'Babilim','messages'=>['Babilim'=>'Babilim','Fills in missing translations for the plugins and themes already installed on your site.'=>'Doplní chybějící překlady pro pluginy a šablony, které jsou již na vašem webu nainstalované.','Translations'=>'Překlady','Babilim Settings'=>'Nastavení Babilim','Settings'=>'Nastavení','You are not allowed to do this.'=>'Nemáte oprávnění k této akci.','Select fewer components: at most %1$d operations per run (you selected %2$d).'=>'Vyberte méně komponent: maximálně %1$d operací na jedno spuštění (vybrali jste %2$d).','That component is not installed on this site, so a translation cannot be requested for it.'=>'Tato komponenta není na tomto webu nainstalována, proto pro ni nelze požádat o překlad.','Already installed.'=>'Již nainstalováno.','Downloaded and installed.'=>'Staženo a nainstalováno.','Babilim has not been enabled for this site yet.'=>'Babilim zatím není pro tento web povolen.','No build is available to download for this locale.'=>'Pro tuto lokalizaci není ke stažení dostupné žádné sestavení.','Rolled back to the previous build.'=>'Vráceno na předchozí sestavení.','Rolled back and reported.'=>'Vráceno zpět a nahlášeno.','Rolled back, but the report could not be sent: %s'=>'Vráceno zpět, ale hlášení se nepodařilo odeslat: %s','Removed.'=>'Odstraněno.','Translation requested.'=>'Překlad byl vyžádán.','This component was already uploaded. Babilim is checking it now.'=>'Tato komponenta již byla nahrána. Babilim ji právě kontroluje.','Upload cancelled.'=>'Nahrávání bylo zrušeno.','Upload complete — translation requested.'=>'Nahrávání dokončeno — překlad byl vyžádán.','This component does not declare a version number, so a translation cannot be requested for it.'=>'Tato komponenta neuvádí číslo verze, proto pro ni nelze požádat o překlad.','This component\'s version number is longer than %d characters, which Babilim cannot handle, so a translation cannot be requested for it.'=>'Číslo verze této komponenty je delší než %d znaků, což Babilim nedokáže zpracovat, proto pro ni nelze požádat o překlad.','A translation cannot be requested for that locale on this site right now.'=>'Pro tuto lokalizaci nelze na tomto webu právě teď požádat o překlad.','Thank you. Your report was sent.'=>'Děkujeme. Vaše hlášení bylo odesláno.','This report does not name a valid plugin or theme and locale.'=>'Toto hlášení neuvádí platný plugin či šablonu a lokalizaci.','Please choose a category for this report.'=>'Vyberte prosím kategorii tohoto hlášení.','This report is missing a valid build to report against.'=>'Tomuto hlášení chybí platné sestavení, ke kterému se vztahuje.','This build is not one this site currently knows about for this component/locale.'=>'Toto sestavení tento web aktuálně nezná pro danou komponentu a lokalizaci.','The field "%1$s" is too long: it has %2$d characters and the limit is %3$d. Nothing was sent; please shorten it and try again.'=>'Pole „%1$s“ je příliš dlouhé: má %2$d znaků a limit je %3$d. Nic nebylo odesláno, zkraťte jej prosím a zkuste to znovu.','Original string'=>'Původní řetězec','String context'=>'Kontext řetězce','Current translation'=>'Aktuální překlad','Suggested translation'=>'Navrhovaný překlad','Note (optional)'=>'Poznámka (volitelné)','Where you saw this (optional)'=>'Kde jste to viděli (volitelné)','Babilim sync is temporarily delayed by the service (rate limited); it will try again after %s.'=>'Synchronizace Babilim je služnou dočasně zpožděna (omezení počtu požadavků); další pokus proběhne po %s.','The locale you added is not valid: use a WordPress locale code such as ll_CC (letters, digits, underscore, hyphen or @, at most %d characters). Nothing was saved.'=>'Zadaná lokalizace není platná: použijte kód lokalizace WordPress ve tvaru ll_CC (písmena, číslice, podtržítko, pomlčka nebo @, nejvýše %d znaků). Nic nebylo uloženo.','Settings saved.'=>'Nastavení bylo uloženo.','If this is on, uninstalling also erases this site\'s identity. The paid license attached to this site cannot be restored automatically afterwards; you would have to contact Babilim support at %s to get it back.'=>'Pokud je tato volba zapnutá, odinstalace odstraní také identitu tohoto webu. Placenou licenci přiřazenou k tomuto webu pak nebude možné automaticky obnovit; museli byste kontaktovat podporu Babilim na adrese %s.','Babilim is set to erase this site\'s identity when the plugin is deleted. The paid license attached to this site could then not be restored automatically; you would have to contact Babilim support at %s. To keep the identity, press Cancel, untick "Delete all Babilim data on uninstall" in the Babilim settings, and deactivate again. Deactivate anyway?'=>'Babilim je nastaven tak, aby při smazání pluginu odstranil identitu tohoto webu. Placenou licenci přiřazenou k tomuto webu pak nebude možné automaticky obnovit; museli byste kontaktovat podporu Babilim na adrese %s. Chcete-li identitu zachovat, stiskněte Zrušit, v nastavení Babilim zrušte zaškrtnutí volby „Při odinstalaci odstranit všechna data Babilim“ a deaktivujte znovu. Přesto deaktivovat?','%1$d site on this network is set to erase its Babilim identity when the plugin is deleted. The paid license attached to that site could then not be restored automatically; you would have to contact Babilim support at %2$s. To keep the identity, press Cancel, untick "Delete all Babilim data on uninstall" in that site\'s Babilim settings, and deactivate again. Deactivate anyway?'=>'%1$d web v této síti je nastaven tak, aby při smazání pluginu odstranil svou identitu Babilim. Placenou licenci přiřazenou k tomuto webu pak nebude možné automaticky obnovit; museli byste kontaktovat podporu Babilim na adrese %2$s. Chcete-li identitu zachovat, stiskněte Zrušit, v nastavení Babilim tohoto webu zrušte zaškrtnutí volby „Při odinstalaci odstranit všechna data Babilim“ a deaktivujte znovu. Přesto deaktivovat?' . "\0" . '%1$d weby v této síti jsou nastaveny tak, aby při smazání pluginu odstranily svou identitu Babilim. Placenou licenci přiřazenou k těmto webům pak nebude možné automaticky obnovit; museli byste kontaktovat podporu Babilim na adrese %2$s. Chcete-li identity zachovat, stiskněte Zrušit, v nastavení Babilim každého webu zrušte zaškrtnutí volby „Při odinstalaci odstranit všechna data Babilim“ a deaktivujte znovu. Přesto deaktivovat?' . "\0" . '%1$d webů v této síti je nastaveno tak, aby při smazání pluginu odstranilo svou identitu Babilim. Placenou licenci přiřazenou k těmto webům pak nebude možné automaticky obnovit; museli byste kontaktovat podporu Babilim na adrese %2$s. Chcete-li identity zachovat, stiskněte Zrušit, v nastavení Babilim každého webu zrušte zaškrtnutí volby „Při odinstalaci odstranit všechna data Babilim“ a deaktivujte znovu. Přesto deaktivovat?','This network has too many sites to check them one by one, and some of them may be set to erase their Babilim identity when the plugin is deleted. The paid license attached to such a site could then not be restored automatically; you would have to contact Babilim support at %s. To keep the identities, press Cancel, untick "Delete all Babilim data on uninstall" in each site\'s Babilim settings, and deactivate again. Deactivate anyway?'=>'Tato síť má příliš mnoho webů na to, aby se daly kontrolovat jeden po druhém, a některé z nich mohou být nastaveny tak, že při odstranění pluginu smažou svou identitu Babilim. Placenou licenci připojenou k takovému webu by pak nebylo možné obnovit automaticky; museli byste kontaktovat Podpora Babilim na %s. Chcete-li identity zachovat, stiskněte Zrušit, v nastavení Babilim každého webu zrušte zaškrtnutí volby „Při odinstalaci odstranit všechna data Babilim“ a poté deaktivujte znovu. Přesto deaktivovat?','Open Babilim settings'=>'Otevřít nastavení Babilim','Babilim could not verify this site, so nothing is downloaded or installed.'=>'Babilim nemohl tento web ověřit, a proto se nic nestahuje ani neinstaluje.','The service could not reach your site. A firewall, security plugin or host rule is probably blocking the request; please allow requests to /wp-json/babilim/v1/challenge.'=>'Služba se nemohla spojit s vaším webem. Požadavek pravděpodobně blokuje firewall, bezpečnostní plugin nebo pravidlo hostingu; povolte prosím požadavky na /wp-json/babilim/v1/challenge.','Your site took too long to answer. Please try again later, and check that your host is not too slow or overloaded.'=>'Váš web odpovídal příliš dlouho. Zkuste to prosím později a zkontrolujte, zda hosting není příliš pomalý nebo přetížený.','Your site answered, but not with what was expected. The REST API may be rewritten by another plugin, or that endpoint may be cached; please exclude /wp-json/babilim/v1/challenge from caching and rewriting.'=>'Váš web odpověděl, ale ne tím, co se očekávalo. REST API může být přepsáno jiným pluginem nebo může být tento koncový bod ukládán do mezipaměti; vyloučte prosím /wp-json/babilim/v1/challenge z ukládání do mezipaměti a přepisování.','Please check that your site can be reached from the internet, then try again.'=>'Zkontrolujte prosím, zda je váš web dostupný z internetu, a zkuste to znovu.','Re-verify'=>'Znovu ověřit','This site is over the size the service accepts in one sync, so some items were left out: %1$d components and %2$d locales.'=>'Tento web přesahuje velikost, kterou služba přijme v jedné synchronizaci, proto byly některé položky vynechány: komponenty: %1$d a jazykové verze: %2$d.','This site is verified.'=>'Tento web je ověřen.','Registration restarted.'=>'Registrace byla spuštěna znovu.','Sync complete.'=>'Synchronizace dokončena.','Babilim is enabling and checking this site… Reload this page or wait for the scheduled check to finish.'=>'Babilim tento web povoluje a kontroluje… Znovu načtěte stránku nebo počkejte na dokončení naplánované kontroly.','Babilim could not finish enabling (%1$s): %2$s'=>'Babilim nemohl dokončit povolení (%1$s): %2$s','A host that serves only one PHP request at a time cannot complete this step.'=>'Hosting, který obsluhuje vždy jen jeden požadavek PHP, tento krok nemůže dokončit.','Babilim is enabled: this site is verified and %d component was found.'=>'Babilim je povolen: tento web je ověřen a byla nalezena %d komponenta.' . "\0" . 'Babilim je povolen: tento web je ověřen a byly nalezeny %d komponenty.' . "\0" . 'Babilim je povolen: tento web je ověřen a bylo nalezeno %d komponent.','Babilim is disabled. Nothing more is sent; translations already installed keep working.'=>'Babilim je zakázán. Již se nic neodesílá; již nainstalované překlady nadále fungují.','Supplementary translation index rebuilt.'=>'Doplňkový index překladů byl znovu vytvořen.','Sweep complete: %d file deleted.'=>'Vyčištění dokončeno: smazán %d soubor.' . "\0" . 'Vyčištění dokončeno: smazány %d soubory.' . "\0" . 'Vyčištění dokončeno: smazáno %d souborů.','Removed %d installed component.'=>'Odstraněna %d nainstalovaná komponenta.' . "\0" . 'Odstraněny %d nainstalované komponenty.' . "\0" . 'Odstraněno %d nainstalovaných komponent.','Automatic installs are now off; turn them on again in the settings if you want them.'=>'Automatické instalace jsou nyní vypnuté; chcete-li je znovu, zapněte je v nastavení.','Babilim finds the plugins and themes on this site that have no translation for your language and installs one for each.'=>'Babilim najde pluginy a motivy na tomto webu, které nemají překlad do vašeho jazyka, a pro každý z nich nainstaluje jeden.','Languages found on this site: %s.'=>'Jazyky nalezené na tomto webu: %s.','Available translations can be installed with one click, and missing ones can be requested. After that, new translations and updates are installed automatically (on the free plan, only for plugins and themes that already use a free slot).'=>'Dostupné překlady lze nainstalovat jedním kliknutím a chybějící lze vyžádat. Poté se nové překlady a aktualizace instalují automaticky (v bezplatném tarifu pouze pro pluginy a motivy, které již využívají bezplatný slot).','The free plan covers a limited number of plugins and themes; your exact quota is shown in Settings after you enable Babilim.'=>'Bezplatný tarif pokrývá omezený počet pluginů a motivů; vaši přesnou kvótu uvidíte v Nastavení po povolení Babilim.','What is sent when you enable Babilim'=>'Co se odesílá při povolení Babilim','Enabling…'=>'Povolování…','Enable Babilim'=>'Povolit Babilim','By clicking Enable, you agree to send the information listed above to Babilim.'=>'Kliknutím na Povolit souhlasíte s odesláním výše uvedených informací službě Babilim.','Check again now'=>'Zkontrolovat znovu nyní','Babilim installed %d translation automatically since your last visit.'=>'Babilim od vaší poslední návštěvy automaticky nainstaloval %d překlad.' . "\0" . 'Babilim od vaší poslední návštěvy automaticky nainstaloval %d překlady.' . "\0" . 'Babilim od vaší poslední návštěvy automaticky nainstaloval %d překladů.','Babilim is enabling and checking this site… (last attempt: %s)'=>'Babilim tento web povoluje a kontroluje… (poslední pokus: %s)','Check again'=>'Zkontrolovat znovu','No components synced yet.'=>'Zatím nebyly synchronizovány žádné komponenty.','%d succeeded'=>'%d úspěšných' . "\0" . '%d úspěšných' . "\0" . '%d úspěšných','%d skipped'=>'%d přeskočeno' . "\0" . '%d přeskočeno' . "\0" . '%d přeskočeno','%d failed'=>'%d selhalo' . "\0" . '%d selhalo' . "\0" . '%d selhalo','%d not yet tried'=>'%d ještě nezkoušeno' . "\0" . '%d ještě nezkoušeno' . "\0" . '%d ještě nezkoušeno','Bulk %s:'=>'Hromadně %s:','%1$s nothing to do.'=>'%1$s není co dělat.','%1$s %2$s.'=>'%1$s %2$s.','%1$s (%2$s): %3$s'=>'%1$s (%2$s): %3$s','Continuing…'=>'Pokračuje se…','Continue next batch (%d left)'=>'Pokračovat další dávkou (zbývá %d)','Search components'=>'Hledat komponenty','These are the languages this site uses. You can change them in %s.'=>'Toto jsou jazyky, které tento web používá. Můžete je změnit v %s.','Upload this component?'=>'Nahrát tuto komponentu?','There is no upload waiting for confirmation.'=>'Nečeká žádné nahrání na potvrzení.','Back'=>'Zpět','To translate this component, Babilim needs its source.'=>'K překladu této komponenty potřebuje Babilim její zdrojový kód.','The entire plugin or theme directory of %1$s (version %2$s) will be uploaded to Babilim.'=>'Celý adresář pluginu nebo šablony %1$s (verze %2$s) bude nahrán do Babilim.','If that directory contains keys, logs or customer data, they will be uploaded too. The service removes common sensitive files (configuration, environment, database dumps, logs, keys) but cannot guarantee it finds everything.'=>'Pokud tento adresář obsahuje klíče, protokoly nebo zákaznická data, budou nahrána také. Služba odstraňuje běžné citlivé soubory (konfigurace, prostředí, výpisy databáze, protokoly, klíče), ale nemůže zaručit, že najde vše.','The upload is kept until you ask Babilim to delete it.'=>'Nahraná data se uchovávají, dokud nepožádáte Babilim o jejich smazání.','It is stored by the service\'s hosting provider and processed by AI models to produce the translation.'=>'Jsou uložena u poskytovatele hostingu služby a ke zpracování překladu je zpracovávají modely umělé inteligence.','The original text and the translations made from it will be provided to other sites that install the same version.'=>'Původní text a z něj vytvořené překlady budou poskytnuty dalším webům, které instalují stejnou verzi.','By continuing you confirm that you have the right to upload this component.'=>'Pokračováním potvrzujete, že máte právo tuto komponentu nahrát.','Upload and request'=>'Nahrát a požádat','Uploading…'=>'Nahrávání…','Cancel'=>'Zrušit','Uploading'=>'Nahrávání','There is no upload in progress.'=>'Žádné nahrávání neprobíhá.','Uploading part %1$d of %2$d…'=>'Nahrávání části %1$d z %2$d…','Continue'=>'Pokračovat','Confirm'=>'Potvrdit','Remove'=>'Odstranit','Roll back'=>'Vrátit zpět','Nothing to confirm.'=>'Není co potvrzovat.','Choose a language'=>'Vyberte jazyk','Roll back and report'=>'Vrátit zpět a nahlásit','Report a problem'=>'Nahlásit problém','Nothing to choose.'=>'Není z čeho vybírat.','%1$s: %2$s. Choose the language.'=>'%1$s: %2$s. Vyberte jazyk.','Supplementary translations'=>'Doplňkové překlady','Each component\'s own contribution to each locale\'s shared default-domain supplement.'=>'Příspěvek každé komponenty do sdíleného doplňku výchozí domény každého jazyka.','Component'=>'Komponenta','Language'=>'Jazyk','Included in index'=>'Zahrnuto v indexu','Entries'=>'Položky','Conflicting keys'=>'Konfliktní klíče','Yes'=>'Ano','No — component inactive'=>'Ne – komponenta je neaktivní','No — installed version differs from the active one'=>'Ne – nainstalovaná verze se liší od aktivní','No — component removed'=>'Ne – komponenta byla odebrána','No'=>'Ne','Only a network administrator can do this, because it changes translation files shared by every site on this network.'=>'Tuto akci může provést pouze správce sítě, protože mění soubory překladů sdílené všemi weby v této síti.','Babilim could not finish verifying this site (the service could not reach it back). Registration is paused.'=>'Babilim nemohl dokončit ověření tohoto webu (služba se k němu nedokázala zpětně připojit). Registrace je pozastavena.','This site already has an active registration that can no longer be recovered automatically.'=>'Tento web již má aktivní registraci, kterou již nelze automaticky obnovit.','Restart registration'=>'Znovu zahájit registraci','Babilim settings'=>'Nastavení Babilim','General'=>'Obecné','Advanced'=>'Pokročilé','Languages'=>'Jazyky','Automatic installs'=>'Automatické instalace','Install available translations automatically'=>'Automaticky instalovat dostupné překlady','On the free plan, only components that already use one of your free slots are installed automatically, so no new slot is taken.'=>'V bezplatném tarifu se automaticky instalují pouze komponenty, které již využívají některý z vašich bezplatných slotů, takže se nezabere žádný nový slot.','This site is part of a multisite network, which does not install new translations automatically. Translations that are already installed are still updated.'=>'Tento web je součástí multisite sítě, která automaticky neinstaluje nové překlady. Již nainstalované překlady se nadále aktualizují.','Custom overrides'=>'Vlastní přepsání','Keep my own translation overrides when purging everything or uninstalling this plugin.'=>'Ponechat mé vlastní přepsání překladů při úplném vymazání nebo odinstalaci tohoto pluginu.','Translation files you put in %s always take priority over Babilim\'s. They are kept unless you uncheck this.'=>'Soubory překladů umístěné do %s mají vždy přednost před soubory Babilim. Zůstanou zachovány, dokud toto nezrušíte.','Uninstall'=>'Odinstalace','Delete all Babilim data on uninstall'=>'Při odinstalaci odstranit všechna data Babilim','Off by default: deleting the plugin keeps this site\'s identity, so a reinstall can reuse it.'=>'Ve výchozím stavu vypnuto: smazáním pluginu se identita tohoto webu zachová, takže ji lze při opětovné instalaci znovu použít.','Account'=>'Účet','Save changes'=>'Uložit změny','Disable Babilim'=>'Zakázat Babilim','Installed translations are kept, but no further checks or downloads will run.'=>'Nainstalované překlady zůstanou zachovány, ale již nebudou probíhat žádné kontroly ani stahování.','Disable Babilim? Installed translations are kept, but no further checks or downloads will run.'=>'Zakázat Babilim? Nainstalované překlady zůstanou zachovány, ale již nebudou probíhat žádné kontroly ani stahování.','This site is not registered with Babilim yet.'=>'Tento web ještě není zaregistrován v Babilim.','This site is already licensed. Reload the page.'=>'Tento web již má licenci. Znovu načtěte stránku.','Checkout is not available for this site right now.'=>'Pokladna pro tento web momentálně není k dispozici.','Could not start checkout: %s'=>'Nepodařilo se zahájit platbu v pokladně: %s','Babilim is not enabled.'=>'Babilim není povolen.','Not registered yet'=>'Zatím není zaregistrováno','Not verified'=>'Neověřeno','Verified'=>'Ověřeno','Status'=>'Stav','Licensed'=>'Licencováno','Partner'=>'Partner','Free'=>'Zdarma','License'=>'Licence','Upgrade this site'=>'Upgradovat tento web','One-time purchase for this site: %1$s %2$s. Includes all future translation updates. Payment is handled by Paddle in a new tab.'=>'Jednorázový nákup pro tento web: %1$s %2$s. Zahrnuje všechny budoucí aktualizace překladů. Platbu zajišťuje Paddle na nové kartě.','This issues a new restore code and the previous one stops working. Continue?'=>'Tím se vydá nový kód pro obnovení a předchozí přestane fungovat. Pokračovat?','Show a new restore code'=>'Zobrazit nový kód pro obnovení','rc_…'=>'rc_…','Restore code'=>'Kód pro obnovení','Restore purchase'=>'Obnovit nákup','Bought a license for this domain before? Enter the restore code you received at checkout.'=>'Zakoupili jste již dříve licenci pro tuto doménu? Zadejte kód pro obnovení, který jste obdrželi v pokladně.','That does not look like a restore code.'=>'Toto nevypadá jako kód pro obnovení.','This restore code was not recognised for this site.'=>'Tento kód pro obnovení nebyl pro tento web rozpoznán.','Too many attempts. Try again tomorrow.'=>'Příliš mnoho pokusů. Zkuste to znovu zítra.','This site must be verified first.'=>'Tento web musí být nejprve ověřen.','Could not restore the purchase: %s'=>'Nákup se nepodařilo obnovit: %s','Purchase restored. This site is now licensed.'=>'Nákup byl obnoven. Tento web je nyní licencován.','This site has no purchase to show a code for.'=>'Tento web nemá žádný nákup, pro který by bylo možné zobrazit kód.','Could not show a new restore code: %s'=>'Nový kód pro obnovení se nepodařilo zobrazit: %s','Your new restore code: %s. Keep it somewhere safe — the previous code no longer works.'=>'Váš nový kód pro obnovení: %s. Uložte si ho na bezpečné místo — předchozí kód již nefunguje.','What is sent when Babilim checks this site'=>'Co se odesílá, když Babilim kontroluje tento web','(detected)'=>'(zjištěno)','No language is managed yet.'=>'Zatím není spravován žádný jazyk.','Babilim adds translations for every language checked here.'=>'Babilim přidává překlady pro každý zde zaškrtnutý jazyk.','Add another language'=>'Přidat další jazyk','Choose a language…'=>'Vyberte jazyk…','Could not load the full WordPress.org locale list from the service, so no other language can be added right now.'=>'Úplný seznam jazyků z WordPress.org se nepodařilo ze služby načíst, proto nyní nelze přidat žádný další jazyk.','Theme'=>'Šablona','Plugin'=>'Plugin','Free quota'=>'Bezplatná kvóta','Downloads: %1$d/%2$d (%3$s)'=>'Stažení: %1$d/%2$d (%3$s)','Supplementary translation index'=>'Doplňkový index překladů','Built'=>'Sestaveno','Included'=>'Zahrnuto','Excluded'=>'Vyloučeno','Already in WordPress core'=>'Již v jádru WordPressu','Supplementary translation maintenance'=>'Údržba doplňkových překladů','Maintenance status is not available right now.'=>'Stav údržby momentálně není k dispozici.','A cleanup was paused on %1$s: %2$s. Nothing was deleted.'=>'Čištění bylo pozastaveno dne %1$s: %2$s. Nic nebylo smazáno.','Last cleanup on %1$s: %2$d newly marked, %3$d file(s) deleted, %4$d record(s) removed.'=>'Poslední vyčištění %1$s: nově označeno %2$d, smazáno souborů: %3$d, odstraněno záznamů: %4$d.','No cleanup has run yet.'=>'Zatím neproběhlo žádné vyčištění.','A translation-index write conflicted with another request on %1$s (%2$s) and was not applied; the most recent version was kept.'=>'Zápis do indexu překladů se %1$s (%2$s) dostal do konfliktu s jiným požadavkem a nebyl použit; byla zachována nejnovější verze.','A translation-index write on %1$s (%2$s) could not be completed and was not applied (%3$s).'=>'Zápis do indexu překladů %1$s (%2$s) se nepodařilo dokončit a nebyl použit (%3$s).','Maintenance'=>'Údržba','Rebuild index now'=>'Znovu vytvořit index','Sweep now'=>'Vyčistit nyní','Danger zone'=>'Nebezpečná zóna','Removes every language file Babilim has installed for every plugin and theme on this site.'=>'Odstraní všechny jazykové soubory, které Babilim nainstaloval pro všechny pluginy a šablony na tomto webu.','Remove everything Babilim installed? This deletes every language file it installed for every plugin and theme on this site.'=>'Odstranit vše, co Babilim nainstaloval? Tím se smažou všechny jazykové soubory, které Babilim nainstaloval pro všechny pluginy a šablony na tomto webu.','Remove everything Babilim installed'=>'Odstranit vše, co Babilim nainstaloval','This string is too long to be sent as a report, so no report form is offered for it.'=>'Tento řetězec je příliš dlouhý na odeslání v hlášení, proto pro něj není nabídnut formulář hlášení.','Category'=>'Kategorie','Choose a category…'=>'Vyberte kategorii…','Roll back and send report'=>'Vrátit zpět a odeslat hlášení','Send report'=>'Odeslat hlášení','Some of this component\'s text is hard-coded by its author and can\'t be translated by a language pack.'=>'Část textu této komponenty je pevně zakódována jejím autorem a nelze ji přeložit jazykovým balíčkem.','WordPress.org'=>'WordPress.org','Bundled with the theme'=>'Součást šablony','Bundled with the plugin'=>'Součást pluginu','Upload was not accepted'=>'Nahrání nebylo přijato','Upload expired before it finished'=>'Nahrání vypršelo před dokončením','No translation'=>'Žádný překlad','Upload in progress — continue or cancel'=>'Probíhá nahrávání — pokračujte nebo zrušte','Scheduled, waiting to be processed'=>'Naplánováno, čeká na zpracování','Translating…'=>'Překládání…','Translation failed'=>'Překlad selhal','Free quota used'=>'Bezplatná kvóta vyčerpána','Needs a paid license'=>'Vyžaduje placenou licenci','Not supported'=>'Nepodporováno','Status unknown'=>'Stav neznámý','translation statusInstalled'=>'Nainstalováno','Update available'=>'K dispozici je aktualizace','Removed after a failed integrity check'=>'Odstraněno po neúspěšné kontrole integrity','Installed · built for %s, new version scheduled'=>'Nainstalováno · vytvořeno pro %s, nová verze je naplánována','Installed · built for a different version, new version scheduled'=>'Nainstalováno · vytvořeno pro jinou verzi, nová verze je naplánována','Installed · built for %s, translating the new version…'=>'Nainstalováno · vytvořeno pro %s, překládá se nová verze…','Installed · built for a different version, translating the new version…'=>'Nainstalováno · vytvořeno pro jinou verzi, překládá se nová verze…','Installed · built for %1$s, this site has %2$s'=>'Nainstalováno · vytvořeno pro %1$s, tento web má %2$s','Installed · built for %s'=>'Nainstalováno · vytvořeno pro %s','Installed · built for a different version'=>'Nainstalováno · vytvořeno pro jinou verzi','Installed · built for %s, new version failed'=>'Nainstalováno · vytvořeno pro verzi %s, nová verze selhala','Installed · built for a different version, new version failed'=>'Nainstalováno · vytvořeno pro jinou verzi, nová verze selhala','Installed · built for %s, new version needs a paid license'=>'Nainstalováno · vytvořeno pro verzi %s, nová verze vyžaduje placenou licenci','Installed · built for a different version, new version needs a paid license'=>'Nainstalováno · vytvořeno pro jinou verzi, nová verze vyžaduje placenou licenci','Installed · built for %s, free quota used'=>'Nainstalováno · vytvořeno pro verzi %s, bezplatná kvóta vyčerpána','Installed · built for a different version, free quota used'=>'Nainstalováno · vytvořeno pro jinou verzi, bezplatná kvóta vyčerpána','translation statusAvailable'=>'K dispozici','Installed · %s'=>'Nainstalováno · %s','Available · %s'=>'K dispozici · %s','Update'=>'Aktualizovat','Download'=>'Stáhnout','Updating…'=>'Aktualizace…','Downloading…'=>'Stahování…','Retry request'=>'Zkusit požadavek znovu','Request newer translation'=>'Vyžádat novější překlad','Request translation'=>'Vyžádat překlad','Requesting…'=>'Vyžadování…','Requesting a translation uses one of your free slots, unless this component already uses one. A failed translation does not give the slot back.'=>'Vyžádání překladu využije jeden z vašich bezplatných slotů, pokud jej tato komponenta již nevyužívá. Neúspěšný překlad slot nevrací.','If this component does not use one of your free slots yet, requesting a translation uses one. A failed translation does not give the slot back. Continue?'=>'Pokud tato komponenta ještě nevyužívá jeden z vašich bezplatných slotů, vyžádání překladu jeden využije. Neúspěšný překlad slot nevrací. Pokračovat?','No plugins or themes found.'=>'Nebyly nalezeny žádné pluginy ani šablony.','Clear filters'=>'Zrušit filtry','No components match these filters. %s'=>'Těmto filtrům neodpovídají žádné komponenty. %s','Select all'=>'Vybrat vše','All'=>'Vše','Available'=>'K dispozici','Updates'=>'Aktualizace','Requestable'=>'Lze vyžádat','Installed'=>'Nainstalováno','Plugins'=>'Pluginy','Themes'=>'Šablony','All languages'=>'Všechny jazyky','%d to install'=>'%d k instalaci' . "\0" . '%d k instalaci' . "\0" . '%d k instalaci','Language:'=>'Jazyk:','Bulk actions apply to every matching language of each selected component.'=>'Hromadné akce se použijí na každý odpovídající jazyk každé vybrané komponenty.','Bulk actions apply only to the selected language of each selected component.'=>'Hromadné akce se použijí pouze na vybraný jazyk každé vybrané komponenty.','Version %s'=>'Verze %s','Theme · %s'=>'Šablona · %s','Plugin · %s'=>'Plugin · %s','Remove the %2$s translation of %1$s from this site?'=>'Odebrat z tohoto webu překlad komponenty %1$s pro jazyk %2$s?','Roll back the %2$s translation of %1$s to the previous build?'=>'Vrátit zpět překlad komponenty %1$s pro jazyk %2$s na předchozí sestavení?','%1$s: %2$s'=>'%1$s: %2$s','%1$s: %2$s (%3$s)'=>'%1$s: %2$s (%3$s)','The registration challenge is not in the expected form.'=>'Registrační výzva nemá očekávaný tvar.','That is not a valid build identifier.'=>'Toto není platný identifikátor sestavení.','Refusing to write outside the Babilim language-file directory.'=>'Odmítnuto zapisovat mimo adresář jazykových souborů Babilim.','Could not write the downloaded package to disk.'=>'Stažený balíček se nepodařilo zapsat na disk.','Unexpected HTTP %d response.'=>'Neočekávaná odpověď HTTP %d.','This site\'s URL, so the service can verify you own it.'=>'URL tohoto webu, aby služba mohla ověřit, že jej vlastníte.','Your WordPress version, to serve compatible translation files.'=>'Vaše verze WordPressu, aby bylo možné poskytovat kompatibilní soubory překladů.','Your PHP version, for compatibility.'=>'Vaše verze PHP, kvůli kompatibilitě.','This plugin\'s own version, so the service can tell you to update it if it\'s too old to talk to.'=>'Verze tohoto pluginu, aby vám služba mohla doporučit jeho aktualizaci, pokud je plugin příliš starý na to, aby s ní mohl komunikovat.','This site\'s configured locale.'=>'Nastavené jazykové prostředí tohoto webu.','Every locale in use on this site (site locale, installed language packs, user locales, and any you add manually). No locale is treated differently from another.'=>'Každé jazykové prostředí používané na tomto webu (jazykové prostředí webu, nainstalované jazykové balíčky, jazyková prostředí uživatelů a všechna, která přidáte ručně). Se všemi jazykovými prostředími se zachází stejně.','(a public key generated for this site)'=>'(veřejný klíč vygenerovaný pro tento web)','This site\'s install public key, used to prove requests genuinely come from this site. Only the public half is ever sent.'=>'Veřejný klíč instalace tohoto webu, používaný k prokázání, že požadavky skutečně pocházejí z tohoto webu. Odesílá se vždy pouze veřejná část.','Every installed plugin/theme: its slug, version, text domain(s), whether it\'s a wp.org listing, its own bundled locales, and which locales you\'ve already installed a Babilim translation for.'=>'Každý nainstalovaný plugin/šablona: jeho slug, verze, textová doména (domény), zda jde o položku na wp.org, jeho vlastní přibalená jazyková prostředí a pro která jazyková prostředí jste již nainstalovali překlad Babilim.','Only when you confirm an upload for a plugin or theme that is not on WordPress.org: that component\'s entire directory, as a zip.'=>'Pouze když potvrdíte nahrání pluginu nebo šablony, které nejsou na WordPress.org: celý adresář této komponenty jako zip.','(generic codes and coordinates only)'=>'(pouze obecné kódy a souřadnice)','Up to 20 pending diagnostic events (e.g. a file that failed its integrity check), each just a code, component, and locale, and never any string content or translated text.'=>'Až 20 čekajících diagnostických událostí (např. soubor, který neprošel kontrolou integrity), každá obsahuje jen kód, komponentu a jazykové prostředí, nikdy žádný obsah řetězců ani přeložený text.','Unsafe locale: %s'=>'Nebezpečné jazykové prostředí: %s','Manifest unavailable: %s'=>'Manifest není k dispozici: %s','Could not determine active components; the existing merged index was left unchanged.'=>'Nepodařilo se zjistit aktivní komponenty; stávající sloučený index zůstal beze změny.','Could not determine installed plugins/themes; sweep skipped, nothing was deleted.'=>'Nepodařilo se zjistit nainstalované pluginy/šablony; vyčištění bylo přeskočeno, nic nebylo smazáno.','Sweep aborted without orphaning anything: %s.'=>'Vyčištění bylo přerušeno, aniž by cokoli osiřelo: %s.','The cleanup ran, but some of its changes could not be recorded in the translation index; the next cleanup will retry them.'=>'Vyčištění proběhlo, ale některé jeho změny se nepodařilo zaznamenat do indexu překladů; příští vyčištění je zkusí znovu.','The merged index for \'%s\' was rebuilt, but the translation index could not record it; the next rebuild will retry.'=>'Sloučený index pro „%s“ byl znovu sestaven, ale index překladů jej nedokázal zaznamenat; příští sestavení to zkusí znovu.','Could not write the staged merged index.'=>'Nepodařilo se zapsat připravený sloučený index.','Re-parsed entry count did not match the built index.'=>'Počet znovu načtených záznamů neodpovídal sestavenému indexu.','Could not move the merged index for \'%s\' into place; the previous served index (if any) was removed rather than left half-updated. No default-domain supplement is served for this locale until the next successful rebuild.'=>'Sloučený index pro „%s“ se nepodařilo přesunout na místo; předchozí poskytovaný index (pokud existoval) byl odstraněn, aby nezůstal napůl aktualizovaný. Pro toto jazykové prostředí se nebude poskytovat žádný doplněk výchozí domény, dokud nebude příští sestavení úspěšné.','Could not open zip: %s'=>'Nepodařilo se otevřít zip: %s','Zip has no manifest.json.'=>'Zip neobsahuje soubor manifest.json.','manifest.json in the zip is not valid JSON.'=>'Soubor manifest.json v zipu není platný JSON.','manifest.json\'s \'%s\' does not match the expected value.'=>'Hodnota „%s“ v manifest.json neodpovídá očekávané hodnotě.','Another installation is running; try again in a moment.'=>'Probíhá jiná instalace; zkuste to za chvíli znovu.','Not a valid server_build_id: %s'=>'Neplatné server_build_id: %s','The package manifest\'s kind \'%1$s\' does not match the requested kind \'%2$s\'.'=>'Typ „%1$s“ v manifestu balíčku neodpovídá požadovanému typu „%2$s“.','The package\'s text domain \'%1$s\' does not match this site\'s copy of the component (\'%2$s\'), so it was not installed.'=>'Textová doména balíčku „%1$s“ neodpovídá kopii komponenty na tomto webu („%2$s“), proto nebyl nainstalován.','The given domain \'%1$s\' matches neither the package manifest\'s own slug \'%2$s\' nor its text_domain \'%3$s\'.'=>'Zadaná doména „%1$s“ neodpovídá ani vlastnímu slugu manifestu balíčku „%2$s“, ani jeho text_domain „%3$s“.','Unsafe slug: %s'=>'Nebezpečný slug: %s','Unsafe text_domain: %s'=>'Nebezpečná hodnota text_domain: %s','The package has no %s for its own text domain.'=>'Balíček neobsahuje %s pro vlastní textovou doménu.','manifest.json is missing or has an invalid \'%s\'.'=>'Soubor manifest.json chybí nebo obsahuje neplatné pole \'%s\'.','manifest.json is missing or has an invalid \'entries\'.'=>'Soubor manifest.json chybí nebo obsahuje neplatné pole \'entries\'.','manifest.json is missing or has an invalid \'files\'.'=>'Soubor manifest.json chybí nebo obsahuje neplatné pole \'files\'.','manifest.json is missing or has an invalid \'extra_domains\'.'=>'Soubor manifest.json chybí nebo obsahuje neplatné pole \'extra_domains\'.','manifest.json is missing or has an invalid \'build_no\'.'=>'Soubor manifest.json chybí nebo obsahuje neplatné pole \'build_no\'.','manifest.json\'s \'server_build_id\' is not a valid build id.'=>'Pole \'server_build_id\' v souboru manifest.json není platné ID sestavení.','manifest.json\'s \'contract\' is not a valid version string.'=>'Pole \'contract\' v souboru manifest.json není platný řetězec verze.','manifest.json\'s \'status\' must be \'published\'.'=>'Pole \'status\' v souboru manifest.json musí být \'published\'.','manifest.json\'s \'kind\' must be \'plugin\' or \'theme\'.'=>'Pole \'kind\' v souboru manifest.json musí být \'plugin\' nebo \'theme\'.','manifest.json has an invalid \'default_domain_entries\'.'=>'Soubor manifest.json obsahuje neplatné pole \'default_domain_entries\'.','manifest.json has an invalid \'default_domain_files\'.'=>'Soubor manifest.json obsahuje neplatné pole \'default_domain_files\'.','expected_manifest is missing or has an invalid \'%s\'.'=>'expected_manifest chybí nebo obsahuje neplatné pole \'%s\'.','expected_manifest\'s \'server_build_id\' is not a valid build id.'=>'Pole \'server_build_id\' v expected_manifest není platné ID sestavení.','No record for %s'=>'Žádný záznam pro %s','One or more served files no longer match the manifest.'=>'Jeden nebo více poskytovaných souborů již neodpovídá manifestu.','No previous build to roll back to.'=>'Neexistuje předchozí sestavení, na které by se dalo vrátit zpět.','The change could not be recorded in the translation index; please try again.'=>'Změnu se nepodařilo zaznamenat do indexu překladů, zkuste to prosím znovu.','Unknown kind: %s'=>'Neznámý druh: %s','Unsafe domain: %s'=>'Nebezpečná doména: %s','The text domain \'%1$s\' (%2$s) is already served for another installed component (%3$s); nothing was installed.'=>'Textová doména \'%1$s\' (%2$s) je již poskytována pro jinou nainstalovanou komponentu (%3$s); nic nebylo nainstalováno.','Rolling back would overwrite \'%1$s\' (%2$s), which is now served for another installed component (%3$s); nothing was changed.'=>'Vrácení zpět by přepsalo \'%1$s\' (%2$s), který je nyní poskytován pro jinou nainstalovanou komponentu (%3$s); nic nebylo změněno.','Zip is missing expected file: %s'=>'V archivu ZIP chybí očekávaný soubor: %s','sha256 mismatch for %s'=>'Neshoda sha256 pro %s','The package declares no main translation file.'=>'Balíček nedeklaruje žádný hlavní soubor překladu.','Zip is missing expected default file: %s'=>'V archivu ZIP chybí očekávaný výchozí soubor: %s','sha256 mismatch for default/%s'=>'Neshoda sha256 pro default/%s','Could not stage %s'=>'Nepodařilo se připravit %s','Could not stage default/%s'=>'Nepodařilo se připravit default/%s','Entry count mismatch for %s'=>'Neshoda počtu položek pro %s','Could not verify entry count for %s'=>'Nepodařilo se ověřit počet položek pro %s','l10n.php entry count mismatch for %s'=>'Neshoda počtu položek l10n.php pro %s','Default supplement entry count mismatch.'=>'Neshoda počtu položek výchozího doplňku.','The package produced no servable main translation file.'=>'Balíček nevytvořil žádný použitelný hlavní soubor překladu.','Could not prepare %s for rollback.'=>'Nepodařilo se připravit %s pro vrácení zpět.','Could not back up %s before replacing it.'=>'Nepodařilo se zálohovat %s před jeho nahrazením.','Could not move %s into place.'=>'Nepodařilo se přesunout %s na místo.','English (United States)'=>'Angličtina (Spojené státy)','Babilim_Manifest is unavailable: %s'=>'Babilim_Manifest není k dispozici: %s','could not read _manifest.json: %s'=>'nepodařilo se přečíst _manifest.json: %s','failed to parse _manifest.json: %s'=>'Nepodařilo se zpracovat _manifest.json: %s','_manifest.json has an unexpected structure'=>'Soubor _manifest.json má neočekávanou strukturu.','Could not create the package archive.'=>'Nepodařilo se vytvořit archiv balíčku.','No writable temporary directory is available for packaging.'=>'Pro vytvoření balíčku není k dispozici žádný zapisovatelný dočasný adresář.','A file in the component could not be read, so it was not packaged.'=>'Soubor v komponentě nebylo možné přečíst, proto nebyl zabalen.','Only plugins and themes can be packaged.'=>'Zabalit lze pouze pluginy a šablony.','The component\'s main file was not found.'=>'Hlavní soubor komponenty nebyl nalezen.','The component is not inside the plugins or themes directory.'=>'Komponenta se nenachází v adresáři pluginů ani šablon.','Babilim ran out of time for this step and will continue on the next check.'=>'Pro tento krok vypršel časový limit a Babilim bude pokračovat při další kontrole.','Babilim could not verify this site, so nothing is downloaded or installed until verification succeeds.'=>'Babilim nemohl tento web ověřit, proto se nic nestáhne ani nenainstaluje, dokud ověření neproběhne úspěšně.','Registration response was missing required fields.'=>'V odpovědi na registraci chyběla povinná pole.','No pending challenge to verify.'=>'Žádná čekající výzva k ověření.','Verify response was missing site_token.'=>'V odpovědi na ověření chyběl site_token.','No site id is on file to rotate a token for.'=>'Není uložen žádný identifikátor webu, pro který by bylo možné obnovit token.','Rotate-token response was missing site_token.'=>'V odpovědi na obnovení tokenu chyběl site_token.','nonce must be a hexadecimal string.'=>'Hodnota nonce musí být hexadecimální řetězec.','No pending challenge for this nonce.'=>'Pro tento nonce neexistuje žádná čekající výzva.','Too many requests.'=>'Příliš mnoho požadavků.','This site has %1$d components across %2$d languages, which needs %3$d check batches; Babilim can handle at most %4$d per run. Reduce the managed languages in Settings or deactivate unused plugins and themes, then press Check again now.'=>'Tento web má %1$d komponent v %2$d jazycích, což vyžaduje %3$d dávek kontroly; Babilim jich zvládne najednou nejvýše %4$d. Snižte počet spravovaných jazyků v Nastavení nebo deaktivujte nepoužívané pluginy a šablony a poté znovu stiskněte Zkontrolovat.','Babilim could not finish checking this site.'=>'Babilim nemohl dokončit kontrolu tohoto webu.','This site\'s address is too long for Babilim to register.'=>'Adresa tohoto webu je příliš dlouhá, než aby ji Babilim mohl zaregistrovat.','This site\'s locale code is not one Babilim can register.'=>'Kód jazyka tohoto webu není kód, který by Babilim mohl zaregistrovat.','The download response was missing a usable location.'=>'V odpovědi na stažení chybělo použitelné umístění.','The service\'s upload offer was incomplete.'=>'Nabídka služby pro nahrání byla neúplná.','This component is larger than the service accepts, so it cannot be uploaded.'=>'Tato komponenta je větší, než služba přijímá, a proto ji nelze nahrát.','The packaged component could not be read.'=>'Zabalenou komponentu se nepodařilo přečíst.','A part of the upload kept failing, so the upload was cancelled.'=>'Část nahrávání opakovaně selhávala, proto bylo nahrávání zrušeno.','Could not read: %s'=>'Nelze přečíst: %s']];